import json

def build_grid_v5():
    """Grid with propagation stopping at blocks, not through them."""
    grid = [[0]*8 for _ in range(8)]

    # Colored inputs
    colored = {(0,2):3, (0,5):8, (3,2):7, (3,5):6, (4,0):7, (4,3):6, (7,0):8, (7,3):3}
    for (r,c), val in colored.items():
        grid[r][c] = val

    # Block boundaries
    def is_block(r, c):
        return (1 <= r <= 2 and 3 <= c <= 4) or (5 <= r <= 6 and 1 <= c <= 2)

    # b1_main (c = r + 2): 3 before, 6 after
    for r in range(8):
        c = r + 2
        if 0 <= c < 8 and not is_block(r, c):
            if r >= 3:  # after block
                grid[r][c] = 6

    # b1_anti (c = 5 - r): 8 before, 7 after
    for r in range(8):
        c = 5 - r
        if 0 <= c < 8 and not is_block(r, c):
            if r < 3 and c >= 3:  # only fill before, and not through block
                grid[r][c] = 8
            elif r >= 3 and c <= 2:  # after
                grid[r][c] = 7

    # b2_main (c = r - 4): 7 before, 8 after
    for r in range(8):
        c = r - 4
        if 0 <= c < 8 and not is_block(r, c):
            if r >= 7:  # after
                grid[r][c] = 8

    # b2_anti (c = 7 - r): 6 before, 7 after
    for r in range(8):
        c = 7 - r
        if 0 <= c < 8 and not is_block(r, c):
            if r < 5:  # before (block starts at row 5)
                grid[r][c] = 6
            elif r >= 6 and c >= 0:  # after
                grid[r][c] = 7

    return grid

